#include "spiral_matrix.h"

namespace spiral_matrix {

std::vector<std::vector<unsigned int>> spiral_matrix(std::size_t size) {
    std::vector<std::vector<unsigned int>> matrix(
        size, std::vector<unsigned int>(size));

    if (size == 0) {
        return matrix;
    }

    std::size_t top = 0;
    std::size_t bottom = size - 1;
    std::size_t left = 0;
    std::size_t right = size - 1;
    unsigned int value = 1;

    while (top <= bottom && left <= right) {
        for (std::size_t column = left; column <= right; ++column) {
            matrix[top][column] = value++;
        }
        ++top;

        for (std::size_t row = top; row <= bottom; ++row) {
            matrix[row][right] = value++;
        }

        if (top <= bottom) {
            for (std::size_t column = right; column > left; --column) {
                matrix[bottom][column] = value++;
            }
            matrix[bottom][left] = value++;
            --bottom;
        }

        if (left <= right) {
            for (std::size_t row = bottom; row > top; --row) {
                matrix[row][left] = value++;
            }
            if (bottom >= top) {
                matrix[top][left] = value++;
            }
            ++left;
        }
    }

    return matrix;
}

}  // namespace spiral_matrix
